effect.shader:
const int MAX_OCTAVES = 8;

// Hash sem textura: barato e igual em qualquer GPU. Uma tabela de permutação
// daria ruído de qualidade melhor, mas custaria uma textura extra por efeito.
float hash21(vec2 p) {
    p = fract(p * vec2(127.1, 311.7));
    p += dot(p, p + 34.23);
    return fract(p.x * p.y);
}

float valueNoise(vec2 p) {
    vec2 cell = floor(p);
    vec2 f = fract(p);
    // Suavização com curva S: sem ela as células do ruído aparecem como
    // losangos, porque a interpolação linear tem quina na fronteira.
    vec2 w = f * f * (3.0 - 2.0 * f);

    float a = hash21(cell);
    float b = hash21(cell + vec2(1.0, 0.0));
    float c = hash21(cell + vec2(0.0, 1.0));
    float d = hash21(cell + vec2(1.0, 1.0));

    return mix(mix(a, b, w.x), mix(c, d, w.x), w.y);
}

float fbm(vec2 p, int levels, float gain) {
    float sum = 0.0;
    float amplitude = 1.0;
    float norm = 0.0;

    for (int i = 0; i < MAX_OCTAVES; i++) {
        if (i >= levels) break;
        float n = valueNoise(p);
        if (ridged) {
            // Dobrar o ruído em torno do meio cria cristas afiadas em vez de
            // manchas macias. É o que dá cara de fumaça e de fogo.
            n = 1.0 - abs(n * 2.0 - 1.0);
        }
        sum += n * amplitude;
        norm += amplitude;
        p *= 2.0;
        amplitude *= gain;
    }

    return sum / max(norm, 0.0001);
}

void main() {
    vec4 original = texture(inputImg, acScreenNorm);

    vec2 p = acScreenNorm * vec2(acAspect, 1.0) / max(size, 0.01) * 4.0;
    p += vec2(evolution + acTime * speed, evolution * 0.7);

    float n = fbm(p, clamp(int(octaves + 0.5), 1, MAX_OCTAVES), roughness);

    if (invertNoise) n = 1.0 - n;
    n = clamp((n - 0.5) * contrast + 0.5 + brightness, 0.0, 1.0);

    vec3 tinted = mix(lowColor.rgb, highColor.rgb, n);
    float alpha = mix(lowColor.a, highColor.a, n);

    // O gerador respeita o alfa da camada: aplicado num sólido ele preenche
    // tudo, aplicado num texto ele preenche só as letras.
    fragColor = vec4(tinted, alpha * original.a);
}
